import * as THREE from 'three/webgpu';
import { color, uv, mix, float, positionLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'orbit-product-hero';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const disposables = [];
  const timelines = [];

  // --- Backdrop plane with engineered gradient ---
  const bgGeo = new THREE.PlaneGeometry(7, 6);
  const stopA = color('#0b0b10');
  const stopB = color('#101017');
  const stopC = color('#16161d');
  const vUv = uv();
  const t = vUv.y;
  const lower = mix(stopA, stopB, t.div(0.55).clamp(0, 1));
  const grad = mix(lower, stopC, t.sub(0.55).div(0.45).clamp(0, 1));
  const bgMat = new THREE.MeshBasicNodeMaterial();
  bgMat.colorNode = grad;
  const backdrop = new THREE.Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // --- Contact shadow ---
  const shadowGeo = new THREE.CircleGeometry(1.6, 48);
  const shadowMat = new THREE.MeshBasicNodeMaterial();
  const shadowUv = uv();
  const dist = shadowUv.sub(0.5).length().mul(2.0);
  const alpha = float(1.0).sub(dist.clamp(0, 1)).mul(0.55);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = alpha;
  shadowMat.transparent = true;
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -1.35, 0);
  group.add(shadowMesh);
  disposables.push(shadowGeo, shadowMat);

  // --- Plinth ---
  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.225, 0);
  group.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // --- Watch mesh group (orbits) ---
  const orbitGroup = new THREE.Group();
  orbitGroup.name = 'watch-orbit-group';
  group.add(orbitGroup);

  const glb = ctx.glbLoader.load(config.assets?.meshUrl || '/prism-mock/orrery/meshes/watch.glb');
  const watchRoot = glb.scene ? glb.scene : glb;

  // normalize height to 2.2 units, center at origin, rest top at y=-1.1
  const box = new THREE.Box3().setFromObject(watchRoot);
  const size = new THREE.Vector3();
  box.getSize(size);
  const center = new THREE.Vector3();
  box.getCenter(center);
  const scaleFactor = size.y > 0 ? 2.2 / size.y : 1;
  watchRoot.position.sub(center);
  watchRoot.scale.setScalar(scaleFactor);
  const scaledMinY = (box.min.y - center.y) * scaleFactor;
  watchRoot.position.y += (-1.1 - scaledMinY);

  watchRoot.traverse((child) => {
    if (child.isMesh) {
      const rimNode = color('#ff2a38');
      const baseMat = new THREE.MeshPhysicalNodeMaterial({
        color: child.material?.color ? child.material.color.clone() : new THREE.Color('#c9ccd1'),
        map: child.material?.map || null,
        normalMap: child.material?.normalMap || null,
        roughness: 0.52,
        metalness: 0.55,
        clearcoat: 0.2,
        clearcoatRoughness: 0.4,
      });
      baseMat.anisotropy = 0.8;
      const nrm = positionLocal.x.clamp(-1, 1);
      const rimMask = nrm.mul(-1).add(1).mul(0.5).mul(nrm.lessThan(0).select(float(1), float(0)));
      baseMat.emissiveNode = rimNode.mul(rimMask).mul(1.6);
      child.material = baseMat;
      disposables.push(baseMat);
    }
  });

  orbitGroup.add(watchRoot);

  // --- Text content ---
  const headline = createText({
    text: 'Calibre NA-01',
    font: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
    atlas: ctx.fontAtlas,
  });
  headline.position.set(0, -1.5, 0.01);
  group.add(headline);

  const body = createText({
    text: 'Machined in-house. 41 mm. Grade 5 titanium.',
    font: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: '#e8ecf2',
    atlas: ctx.fontAtlas,
  });
  body.position.set(0, -1.5 - 0.32, 0.01);
  group.add(body);

  const caption = createText({
    text: 'FROM 4200 USD / SHIPS IN 21 DAYS',
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#ff2a38',
    atlas: ctx.fontAtlas,
  });
  caption.position.set(0, -1.5 - 0.5, 0.01);
  group.add(caption);

  // --- Lighting: key + rim + accent signal ---
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.4);
  keyLight.position.set(2.5, 3, 3);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-3, 1.2, -1.5);
  group.add(rimLight);

  const fill = new THREE.AmbientLight(0x404050, 0.4);
  group.add(fill);

  // --- Cinematic primitives ---
  const primitivesConfig = config.cinematicPrimitives || [
    { name: 'orbit', params: { speed: 0.15, radius: 0.6 } },
    { name: 'depth-rotate', params: { maxDeg: 6 } },
  ];

  primitivesConfig.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      ctx.primitives[prim.name](orbitGroup, prim.params);
    }
  });

  // --- Hover handlers driving depth-rotate + weighted-settle ---
  const handlers = {};
  handlers.onPointerMove = (event) => {
    const nx = event.ncX ?? 0;
    const ny = event.ncY ?? 0;
    const maxRad = THREE.MathUtils.degToRad(6);
    const tl = gsap.timeline();
    tl.to(orbitGroup.rotation, {
      x: -ny * maxRad,
      z: nx * maxRad,
      duration: 0.3,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    });
    timelines.push(tl);
  };

  handlers.onPointerLeave = () => {
    const tl = gsap.timeline();
    tl.to(orbitGroup.scale, {
      x: 1.04, y: 1.04, z: 1.04,
      duration: 0.12,
      ease: 'power4.out',
      onComplete: () => {
        gsap.to(orbitGroup.scale, {
          x: 1, y: 1, z: 1,
          duration: 0.9,
          ease: 'power4.out',
        });
      },
    });
    tl.to(orbitGroup.rotation, {
      x: 0, z: 0,
      duration: 0.9,
      ease: 'power4.out',
    }, 0);
    timelines.push(tl);
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    watchRoot.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
    if (headline.userData?.cleanup) headline.userData.cleanup();
    if (body.userData?.cleanup) body.userData.cleanup();
    if (caption.userData?.cleanup) caption.userData.cleanup();
  };

  return group;
}
